package com.enterprise.procurement.admin.mapper;
import org.apache.ibatis.annotations.*; import java.util.*;
@Mapper public interface RelationMapper { @Delete("delete from sys_user_role where user_id=#{userId}") int deleteUserRoles(Long userId); @Insert({"<script>insert into sys_user_role(user_id,role_id) values <foreach collection='roleIds' item='id' separator=','>(#{userId},#{id})</foreach></script>"}) int insertUserRoles(@Param("userId") Long userId,@Param("roleIds") Collection<Long> roleIds); @Delete("delete from sys_role_permission where role_id=#{roleId}") int deleteRolePermissions(Long roleId); @Insert({"<script>insert into sys_role_permission(role_id,permission_id) values <foreach collection='permissionIds' item='id' separator=','>(#{roleId},#{id})</foreach></script>"}) int insertRolePermissions(@Param("roleId") Long roleId,@Param("permissionIds") Collection<Long> permissionIds); @Select("select role_id from sys_user_role where user_id=#{userId}") List<Long> userRoleIds(Long userId); @Select("select permission_id from sys_role_permission where role_id=#{roleId}") List<Long> rolePermissionIds(Long roleId); }
